/* The arena follows the actual viewport; simulation units stay square pixels. */
html,body{height:100%;margin:0;overflow:hidden}.primal-shell{width:100%;max-width:none;height:100dvh;box-sizing:border-box;display:flex;flex-direction:column;padding:10px 16px 0}.masthead{flex-shrink:0}.arena,.primal-shell:fullscreen .arena{flex:1;width:100%;min-height:0;aspect-ratio:auto}.arena canvas{position:absolute;inset:0;width:100%;height:100%;object-fit:fill}.screen{overflow:auto;align-items:safe center}.panel{flex-shrink:0;margin:auto}.touch-controls,footer{flex-shrink:0}footer{padding:8px 0}.primal-shell:fullscreen{align-items:stretch}.primal-shell:fullscreen .masthead,.primal-shell:fullscreen footer{width:100%}.boss-hud{max-width:calc(100% - 24px)}
@media(max-width:600px){.primal-shell{padding:6px 6px 0}.hud{gap:6px;top:10px}.hud>div{min-width:60px}.meter{width:64px}.hunt-counter{max-width:155px}.hunt-counter b{font-size:11px}.panel{padding:16px}.mutation-grid{grid-template-columns:1fr}.mutation-grid button{min-height:0;padding:10px}.mutation-grid img{float:left;margin:0 12px 0 0}.mutation-grid h2{margin:5px 0}.mutation-grid p{margin:5px 0}.touch-controls button{padding:12px}.touch-controls{margin-top:5px}footer{font-size:8px;padding:4px 0}.save-status{display:none}.run-info{font-size:8px;left:8px;right:8px}.toast{max-width:95%;white-space:normal;text-align:center}.screen{padding:8px}}
@media(max-height:500px){.masthead{margin-bottom:4px}.edition,footer{display:none}.touch-controls button{padding:8px}.panel{padding:14px}.screen h1{font-size:24px}.menu-panel h1{font-size:30px}.menu-panel .intro,.menu-panel .fine{display:none}.name-label{margin:8px 0}.touch-controls{margin-top:4px}}

.meat-progress{position:absolute;left:18px;bottom:36px;width:min(300px,calc(100% - 160px));pointer-events:none;color:#efdfb8;background:#101713d9;padding:8px 10px;font-size:10px}.meat-progress>div:first-child{display:flex;justify-content:space-between;gap:8px}.meat-progress .meter{width:100%;height:10px}.meat-progress i{background:#e9b75a}.meat-progress small{font-size:9px}.rarity-card{border:2px solid var(--rarity);box-shadow:inset 0 3px var(--rarity)}.rarity-name{display:block;color:var(--rarity);font-size:11px;margin-bottom:12px}.rarity-card small{color:var(--rarity)}@media(max-width:600px){.meat-progress{left:8px;bottom:30px;padding:6px;width:calc(100% - 155px)}.meat-progress>div:first-child{flex-direction:column;gap:3px}.rarity-name{margin-bottom:5px}}

.boss-tip{display:block;font-size:9px;color:#efdfb8;line-height:1.5;text-shadow:0 1px 2px #101713}.boss-hud[data-boss-phase="2"] .meter i{background:#de954a}.boss-hud[data-boss-phase="2"] b{color:#de954a}

.species-grid img{width:128px;height:128px;image-rendering:pixelated}.selected-species{outline:2px solid #69a4a0}.species-grid article small{display:block;margin:12px 0}.run-info{flex-wrap:wrap}.touch-controls>div:last-child{display:flex;gap:6px;flex-wrap:wrap}.species-grid{grid-template-columns:repeat(auto-fit,minmax(200px,1fr))}

.screen[data-phase="species"]{align-items:flex-start}.screen[data-phase="species"] .panel{width:min(100%,1100px)}

.death-preview{width:144px;height:144px;image-rendering:pixelated}.selected-dino{color:#69a4a0;font-size:12px;margin:0 0 12px}.species-grid img{width:144px;height:144px}

/* Cinematic jungle title sits beside the functional menu. */
.menu-screen{display:flex;justify-content:space-between;align-items:center;padding:clamp(20px,5vw,90px);gap:30px;background:linear-gradient(90deg,#10171322,#10171366)}.menu-screen .menu-panel{width:min(440px,48vw);max-height:calc(100% - 20px);overflow:auto;background:#101713e8;border:1px solid #79944766;box-shadow:0 18px 80px #0008;padding:30px}.jungle-title{pointer-events:none;display:flex;flex-direction:column;gap:18px;text-shadow:5px 7px #101713;font-family:monospace}.jungle-title small{letter-spacing:3px;color:#a2d4c1}.jungle-title strong{font-size:clamp(45px,8vw,112px);line-height:.85;letter-spacing:-5px;color:#edd0a0}.jungle-title em{font-style:normal;color:#dfbc52}.jungle-title span{color:#e8ece1}.cinematic-menu .arena{min-height:650px}.menu-panel h1{font-size:34px}.menu-panel .intro{font-size:14px}
@media(max-width:700px){.jungle-title{display:none}.menu-screen{justify-content:center;padding:14px}.menu-screen .menu-panel{width:min(440px,100%);padding:23px}.cinematic-menu .arena{min-height:650px}}
@media(prefers-reduced-motion:reduce){.jungle-title{animation:none}}
/* Controls and accessible scaling remain inside the responsive arena. */
.joystick{position:relative;width:110px;height:110px;flex:0 0 110px;border:2px solid #8eaa60;border-radius:50%;background:#101713bb;touch-action:none;display:flex;align-items:center;justify-content:center}
.joystick i{width:38px;height:38px;border-radius:50%;background:#e9b75a;pointer-events:none}.touch-controls .dpad{display:none}.touch-controls>div:last-child{display:flex;flex-wrap:wrap;gap:4px}.bindings{display:flex;flex-wrap:wrap;gap:5px}.bindings button{font-size:12px;padding:8px}.screen h1{font-size:calc(clamp(28px,5vw,54px)*var(--text-scale,1))}.screen p,.screen label,.screen button{font-size:calc(14px*var(--text-scale,1))}.hud,.run-info,.meat-progress{font-size:calc(11px*var(--hud-scale,1))}.hud b,.run-info span{font-size:calc(11px*var(--hud-scale,1))}.hud .meter{height:calc(8px*var(--hud-scale,1))}.settings{max-height:56vh;overflow:auto}.touch-controls button{min-height:44px}.joystick:focus-visible{outline:3px solid #fff1c9}

.run-info{background:#101713d9;padding:5px 7px;border:1px solid #50623d88;gap:4px 10px}.action-cooldowns{display:flex;gap:12px;flex:1 0 220px}.action-cooldowns>div{flex:1}.action-cooldowns b{font-size:10px;display:block;margin-bottom:3px}.action-cooldowns .meter{width:100%;height:6px}.action-cooldowns i{background:#69a4a0}.action-cooldowns #attack-fill{background:#efdfb8}.action-cooldowns[data-ready="false"] #ability-ready{color:#de954a}.rarity-card:has(.rarity-name){border-width:2px}

.stat-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stat-grid div{padding:8px;background:#151b19}.stat-grid b,.stat-grid small{display:block}.run-details{margin:16px 0;text-align:left}.run-title{color:#e9b75a;font-size:1.2em}.end-scene{width:100%;max-width:480px;height:auto;image-rendering:pixelated}.run-details[open]{animation:stats-enter .4s ease-out}@keyframes stats-enter{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){.run-details[open]{animation:none}}
.arena canvas.end-scene{position:relative;inset:auto;display:block;width:100%;max-width:480px;height:auto;aspect-ratio:8/3;object-fit:contain;pointer-events:none}.screen:has(.run-details),.screen:has(.upgrade-grid){align-items:flex-start}
/* Overhaul phase 4: achievements, lock hints, skins */
.locked-species img{filter:grayscale(.85) brightness(.7)}.unlock-hint{font-size:11px;color:#c3a35c;margin:6px 0}
.skin-picker{margin:4px 0 16px}.skin-picker h2{font-size:13px;letter-spacing:2px;color:#c3a35c;margin:0 0 8px}.skin-picker div{display:flex;flex-wrap:wrap;gap:6px}.skin-picker button{font-size:12px;padding:8px 12px}.skin-picker button.selected{border-color:#69a4a0;background:#2c4a43}
.achievement-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px;margin:0 0 16px}.achievement{padding:12px;background:#1b2b22;border:1px solid #3d4c33;opacity:.75}.achievement.done{opacity:1;border-color:#c3a35c;background:#26392c}.achievement b{font-size:13px;color:#f1dfbd}.achievement.done b{color:#e9b75a}.achievement p{font-size:12px;color:#b6c0a9;margin:6px 0}.achievement small{font-size:10px;letter-spacing:1px;color:#8eaa60}
.lifetime{display:flex;flex-wrap:wrap;gap:8px 18px;font-size:11px;color:#b6c0a9;margin:0 0 14px}.lifetime b{color:#c3a35c;margin-left:4px}

/* Overhaul phase 5: compact HUD card */
.hud{top:10px;left:12px;right:12px;gap:16px;align-items:flex-start}.hud-card{display:flex;gap:10px;align-items:center;padding:6px 12px 6px 6px;background:#101b16cc;border:1px solid #50623d88;border-radius:40px 8px 8px 40px;min-width:0!important}
.hud-portrait{width:64px;height:64px;image-rendering:pixelated;flex:none}.hud-bars{display:grid;gap:5px}.hud .meter{position:relative;width:min(220px,34vw);height:12px;margin:0;border-radius:2px}.hud .meter.stamina{height:8px}
.hud .meter .segments{position:absolute;inset:0;background-image:linear-gradient(90deg,transparent calc(100% - 2px),#101b16 calc(100% - 2px));pointer-events:none}
.hud .meter b{position:absolute;right:4px;top:-1px;font-size:9px;line-height:12px;color:#fff1c9;text-shadow:0 1px 2px #000}
.hud .cost-mark{position:absolute;top:-3px;bottom:-3px;width:2px;background:#fff1c9;box-shadow:0 0 0 1px #101b16;transform:translateX(-1px)}
.hud .stamina[data-low="true"] i{background:#de954a}.hud .stamina[data-winded="true"]{animation:winded .5s steps(2) infinite}.hud .health[data-low="true"] i{background:#e0503c;animation:winded 1s steps(2) infinite}@keyframes winded{50%{opacity:.55}}
.hud-chips{display:flex;gap:10px;font-size:11px;font-weight:700;color:#efdfb8;white-space:nowrap}.hud-chips span:empty{display:none}#zone-chip{color:#a2d4c1;font-weight:500}
.hud .hunt-counter{background:#101b16aa;padding:6px 10px;border-radius:6px}
.run-info{opacity:.85}#time-label,#skill-label{opacity:.7}
@media(max-width:800px){.hud-portrait{width:44px;height:44px}.hud .meter{width:38vw}.hud-chips{font-size:10px;gap:6px}#zone-chip,#time-label,#skill-label,#level-label{display:none}}
@media(prefers-reduced-motion:reduce){.hud .stamina[data-winded="true"],.hud .health[data-low="true"] i{animation:none}}

/* M2: tilted living-world menu */
.arena{transition:background .6s}.cinematic-menu .arena{background:linear-gradient(180deg,#de954a 0%,#674333 22%,#28372a 46%,#151b19 100%)}
.arena>canvas{transition:transform 1.1s cubic-bezier(.2,.7,.2,1);transform-origin:50% 72%}
.cinematic-menu .arena>canvas{transform-origin:50% 70%;transform:perspective(1100px) rotateX(22deg) scale(1.55)}
.cinematic-menu .arena::after{content:"";position:absolute;inset:0 0 auto 0;height:28%;background:linear-gradient(180deg,#de954a55,transparent);pointer-events:none}
.menu-screen{background:linear-gradient(90deg,#10171300,#101713aa 70%)}
.chosen-dino{display:flex;align-items:center;gap:12px;margin:0 0 14px;padding:8px;background:#1b2b22;border:1px solid #3d4c33}.chosen-dino img{width:64px;height:64px;image-rendering:pixelated}.chosen-dino b{display:block;font-size:16px}.chosen-dino small{color:#a2d4c1;font-size:11px}.chosen-dino button{margin-left:auto;font-size:11px;padding:8px 10px}
.menu-panel .menu-grid{margin:12px 0 14px}.advanced summary{cursor:pointer;font-size:11px;letter-spacing:2px;color:#b6c0a9;margin:6px 0}
.intro-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:6px 0 12px}.intro-cards article{background:#1b2b22;border:1px solid #3d4c33;padding:12px;text-align:center}.intro-cards img{width:96px;height:96px;image-rendering:pixelated;margin:0 auto 6px;display:block;object-fit:contain}.intro-cards b{display:block;margin-bottom:6px}.intro-cards p{font-size:12px;color:#b6c0a9;line-height:1.5;margin:0}
.intro-warning{display:flex;width:96px;height:96px;margin:0 auto 6px;align-items:center;justify-content:center;font-size:44px;color:#fff1c9;background:radial-gradient(circle,#ed7869aa 0 45%,#ed786933 46% 70%,transparent 71%);border-radius:50%;outline:2px dashed #ed7869;outline-offset:-6px}
.skip-intro{font-size:12px;color:#b6c0a9;margin:8px 0}
@media(max-width:800px){.intro-cards{grid-template-columns:1fr}.intro-cards article{display:grid;grid-template-columns:56px 1fr;text-align:left;gap:4px 10px;align-items:center}.intro-cards img,.intro-warning{width:56px;height:56px;grid-row:span 2;margin:0;font-size:26px}.cinematic-menu .arena>canvas{transform:perspective(900px) rotateX(16deg) scale(1.45)}}
@media(prefers-reduced-motion:reduce){.arena>canvas{transition:none}}

/* Review fixes: HUD portrait must not inherit the full-arena canvas rule; cropped thumbnails */
.arena canvas.hud-portrait{position:static!important;inset:auto!important;width:64px!important;height:64px!important;display:block;transform:none!important}
@media(max-width:800px){.arena canvas.hud-portrait{width:44px!important;height:44px!important}}
img.thumb{image-rendering:pixelated;object-fit:contain}.species-grid img.thumb{width:120px;height:120px;margin:0 auto;display:block}.chosen-dino img.thumb{width:56px;height:56px}.intro-cards img.thumb{width:84px;height:84px}
.menu-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.menu-fields .name-label{margin:0}
.menu-screen{justify-content:flex-end}.menu-screen .menu-panel{max-height:calc(100% - 10px);padding:22px 24px}.menu-panel h1{font-size:40px;margin-bottom:10px}
.meat-progress small{display:none}
@media(max-width:800px){.menu-screen{justify-content:center}.menu-fields{grid-template-columns:1fr}}
.menu-screen .menu-panel{margin:0 3% 0 auto}
@media(max-width:800px){.menu-screen .menu-panel{margin:0 auto}}

.patch-link{display:block;margin-top:12px;font-size:12px;letter-spacing:.06em;color:#e9b75a;text-decoration:none;opacity:.85}.patch-link:hover{opacity:1;text-decoration:underline}
/* Records (Hall of Fame / Shame) and the end-of-run card. */
.records-tabs{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}.records-tabs button{flex:1 1 auto;min-width:0}.records-tabs.scopes button{font-size:.85em}
.records-list{display:grid;grid-template-columns:1fr;gap:4px;max-height:min(60vh,420px);overflow-y:auto}.record-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:2px 10px;padding:6px 8px;background:#151b19;overflow-wrap:anywhere}.record-row small{grid-column:1/-1;opacity:.7}
.run-card{margin:12px 0;padding:10px;background:#151b19;border:1px solid #2c3a33;overflow-wrap:anywhere}.run-card .run-title{margin:4px 0;font-size:1.25em}.run-header,.run-title-text,.run-secondary{margin:4px 0}.run-title-text,.run-secondary{opacity:.8}
.rarity-uncommon{color:#a2d4c1}.rarity-rare{color:#69a4a0}.rarity-epic{color:#c79ad8}.rarity-legendary{color:#e7c35a}.rarity-secret{color:#ffffff}
.chips{display:flex;flex-wrap:wrap;gap:6px;align-items:center}.chip{padding:2px 8px;border:1px solid #2c3a33;font-size:.85em}.chip.new{border-color:#e7c35a}.run-cause small{opacity:.7}.death-tip{margin:.2em 0 0;font-size:.9em}.death-tip small{color:#e9b75a;margin-right:.4em}
.records-tabs button.selected{background:#c3a35c;border-color:#c3a35c;color:#15221a;font-weight:800}
.daily-list{width:100%;border-collapse:collapse;margin:10px 0}.daily-list td{padding:8px 6px}.daily-result{color:#e9b75a;font-weight:700;text-align:center;margin:8px 0}
.challenge-list{display:grid;gap:8px;margin:12px 0}.challenge{display:flex;gap:10px;align-items:flex-start;padding:8px 10px;border:1px solid #50623d66;border-radius:6px}.challenge span{display:grid}.challenge small{opacity:.8}.challenge-bonus{text-align:center;color:#e9b75a;font-weight:700}.intro-challenges{border:1px solid #913b32;border-radius:6px;padding:8px 12px;margin:10px 0}.intro-challenges ul{margin:6px 0 0;padding-left:18px}
.arena canvas.guide-model{position:relative;inset:auto;display:block;width:100%;max-width:240px;height:auto;aspect-ratio:2/1;margin:2px auto 6px;background:linear-gradient(180deg,#0000 55%,#28372a 56%,#1e2a20);border-radius:4px;image-rendering:pixelated;pointer-events:none}
#time-label { display: inline-flex; align-items: center; gap: 4px; }
.time-icon { width: 16px; height: 16px; image-rendering: pixelated; flex: none; }
.hud-chips > span{display:inline-flex;align-items:center;gap:2px}
.hud-chips > span[hidden],.chip-icon[hidden]{display:none}
.chip-icon{width:24px;height:24px;flex:none;image-rendering:pixelated}
.a6-control-icon{width:24px;height:24px;image-rendering:pixelated;vertical-align:middle;margin-right:4px}
.a6-control-icon[hidden]{display:none}
.arena canvas.chip-icon,.arena canvas.a6-control-icon{position:static;inset:auto;width:24px;height:24px;display:inline-block;object-fit:contain;transform:none}
.arena canvas.time-icon{position:static;inset:auto;width:16px;height:16px;display:inline-block;object-fit:contain;transform:none}
@media(max-width:800px){.hud-chips{gap:4px}.hud-chips > #zone-chip{display:none}}
/* Species selection cards: one layout for every species (role, diet, playstyle, ability, stat bars). */
.species-grid .species-card{display:flex;flex-direction:column;gap:0;padding:12px 14px 14px}
.species-card header{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase}
.species-price,.species-diet{padding:3px 7px;border:1px solid #50623d;border-radius:3px;background:#172019;white-space:nowrap}
.species-price{color:#c3a35c;border-color:#c3a35c88}.free-price{color:#69a4a0;border-color:#69a4a088}.achievement-price{color:#e5b55b}
.wip-badge{display:inline-block;margin-left:6px;padding:2px 7px;border:1px solid #e5b55b;border-radius:3px;background:#3a2a10;color:#f0c46a;font-size:12px;font-weight:700;letter-spacing:.08em;vertical-align:middle;white-space:nowrap}
.species-diet{color:#b6c0a9}.diet-herbivore{color:#9cc27a}.diet-omnivore{color:#d5c499}.diet-piscivore{color:#7fb3c8}.diet-carnivore{color:#d88a6a}
.species-card h2{margin:6px 0 0;text-align:center}
.species-grid .species-card p.species-role{margin:2px 0 8px;text-align:center;color:#c3a35c;font-size:10px;font-weight:800;letter-spacing:2px;text-transform:uppercase}
.species-grid .species-card p.species-text{margin:0 0 10px;min-height:3.1em}
.species-skill{border-left:3px solid #c3a35c;background:#172019;padding:8px 10px;margin:0 0 10px}
.species-skill>div{display:flex;align-items:center;gap:8px}.species-skill kbd{font-size:9px;padding:2px 5px;letter-spacing:1px}.species-skill b{font-size:13px;color:#f1dfbd}
.species-grid .species-skill p{margin:6px 0 4px}.species-grid .species-skill small{display:block;margin:0;font-size:10px;color:#92a087;letter-spacing:.5px}
.species-stats{display:grid;gap:5px;margin:auto 0 12px}
.species-stat{display:grid;grid-template-columns:64px 1fr 30px;align-items:center;gap:8px;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#92a087}
.species-stat i{display:block;height:6px;background:#101b16;border:1px solid #50623d}.species-stat i b{display:block;height:100%;background:#69a4a0}
.species-stat em{font-style:normal;text-align:right;color:#f1dfbd}
.species-card .unlock-hint{margin:0 0 8px;font-size:11px;color:#e5b55b}
.species-card button{margin-top:0}
.species-grid .species-card img{width:120px;height:120px;margin:0 auto;display:block}
/* HUD time icon: the generic ".arena canvas" rule stretched it over the whole arena as brown blocks. */
.arena canvas.time-icon{position:static!important;inset:auto!important;width:16px!important;height:16px!important;display:inline-block;vertical-align:-3px;margin-right:4px;transform:none!important;pointer-events:none}
/* Holding a touch button must not select HUD or button text; form fields stay selectable. */
.arena,.touch-controls,footer{-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
.arena input,.arena textarea,.arena select{-webkit-user-select:text;user-select:text}
.touch-controls button{-webkit-tap-highlight-color:transparent}
/* Control hints follow the last input: touch shows the on-screen buttons, a gamepad hides them. */
.primal-shell[data-input="touch"] .touch-controls:not([hidden]){display:flex}
.primal-shell[data-input="gamepad"] .touch-controls{display:none!important}
.primal-shell[data-input="touch"] footer .control-hints{display:none}
.mutation-option{display:flex;flex-direction:column;gap:6px;min-width:0}.mutation-option>button[data-mutation]{flex:1}.mutation-grid button.banish{min-height:0;padding:6px 8px;font-size:10px;letter-spacing:1px;text-align:center;background:transparent;border-style:dashed;color:#b6c0a9}.mutation-grid:has(.mutation-option:nth-child(4)){grid-template-columns:repeat(4,1fr)}.mutation-tag{display:block;margin-top:4px}.mutation-tag b{font-weight:700}.evolution-recipe{display:block;margin-top:6px;line-height:1.5}.set-progress{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:11px;color:#b6c0a9;margin:12px 0 0}.set-progress .set-on{color:#dfbc52}.set-progress em{font-style:normal;font-weight:700}.lab-section{margin-top:18px}.locked-track{opacity:.6;border-style:dashed!important}.mastery-line{font-size:11px;color:#dfbc52;margin:4px 0;letter-spacing:.5px}.mastery-line span{color:#b6c0a9}
@media(max-width:600px){.mutation-grid:has(.mutation-option:nth-child(4)){grid-template-columns:1fr}}

/* Run extras: streak, powerups, baby and amber in one HUD line; baby-start toggle in the menu. */
.extras-chip{font:700 11px/1.3 monospace;letter-spacing:.5px;color:#e8ece1;margin-top:3px;white-space:normal;max-width:240px}.extras-chip .streak{color:#de954a}.extras-chip .baby{color:#a8b15b}.extras-chip .amber-count{color:#dfbc52}
.difficulty-pick{border:1px solid #3d4a36;border-radius:6px;margin:8px 0 0;padding:6px 10px;display:flex;flex-wrap:wrap;gap:4px 14px;text-align:left}.difficulty-pick legend{font-size:11px;color:#b6c0a9;padding:0 4px}.difficulty-pick label{display:flex;gap:6px;align-items:center}.difficulty-pick small{flex-basis:100%;color:#b6c0a9;font-size:11px}
.baby-toggle{display:flex;gap:8px;align-items:flex-start;margin:8px 0 0;text-align:left}.baby-toggle small{display:block;color:#b6c0a9;font-size:11px}
/* Touch play (2026-10-14): the game fills the screen and the controls sit on top of it, joystick under the left
   thumb and a round SNES-style button diamond under the right thumb (A attack, B ability, X inspect, Y eat). */
.primal-shell[data-input="touch"][data-phase="playing"]{padding:0}
.primal-shell[data-input="touch"][data-phase="playing"] .arena{border:0;box-shadow:none;min-height:0;width:100%;aspect-ratio:auto}
.primal-shell[data-input="touch"][data-phase="playing"] footer,.primal-shell[data-input="touch"][data-phase="playing"] .masthead .wordmark,.primal-shell[data-input="touch"][data-phase="playing"] .masthead .edition{display:none}
.primal-shell[data-input="touch"][data-phase="playing"] .masthead{position:fixed;z-index:6;bottom:calc(env(safe-area-inset-bottom,0px) + 140px);right:calc(env(safe-area-inset-right,0px) + 150px);margin:0;padding:0}
.primal-shell[data-input="touch"][data-phase="playing"] #pause-button{width:38px;height:38px;padding:0;border-radius:50%;font-size:0;background:#101713b3;border:2px solid #8eaa6099}
.primal-shell[data-input="touch"][data-phase="playing"] #pause-button::before{content:"❚❚";font-size:13px;letter-spacing:-1px;color:#f1dfbd}
.primal-shell[data-input="touch"][data-phase="playing"] .touch-controls:not([hidden]){position:fixed;z-index:5;left:0;right:0;bottom:0;margin:0;display:flex;justify-content:space-between;align-items:flex-end;pointer-events:none;
  padding:0 max(18px,env(safe-area-inset-right,0px)) calc(18px + env(safe-area-inset-bottom,0px)) max(18px,env(safe-area-inset-left,0px))}
.primal-shell[data-input="touch"][data-phase="playing"] .touch-controls>*{pointer-events:auto}
.primal-shell[data-input="touch"][data-phase="playing"] .joystick{width:132px;height:132px;flex:0 0 132px;background:#10171366;border-color:#8eaa60aa}
.primal-shell[data-input="touch"][data-phase="playing"] .joystick i{width:52px;height:52px;background:#e9b75ad9;box-shadow:0 2px 0 #7a5a24}
.primal-shell[data-input="touch"][data-phase="playing"] .touch-controls>div:last-child{display:grid;grid-template-columns:repeat(3,58px);grid-template-rows:repeat(3,58px);gap:2px;flex-wrap:nowrap}
.primal-shell[data-input="touch"][data-phase="playing"] .touch-controls>div:last-child button{width:62px;height:62px;min-height:0;margin:-2px;padding:0;border-radius:50%;font-size:8.5px;font-weight:800;letter-spacing:0;white-space:nowrap;line-height:1.05;
  color:#fff7e0;border:2px solid #0d120f;box-shadow:inset 0 -4px 0 #0005,0 3px 0 #0d120f99;text-shadow:0 1px 0 #0008;overflow:hidden;display:flex;align-items:center;justify-content:center;text-align:center;word-break:break-word}
.primal-shell[data-input="touch"][data-phase="playing"] .touch-controls>div:last-child button:active{transform:translateY(2px);box-shadow:inset 0 -2px 0 #0005}
.primal-shell[data-input="touch"] .pad-a{grid-area:2/3;background:#b5483a}
.primal-shell[data-input="touch"] .pad-b{grid-area:3/2;background:#c99a2e}
.primal-shell[data-input="touch"] .pad-x{grid-area:1/2;background:#3f7f9a}
.primal-shell[data-input="touch"] .pad-y{grid-area:2/1;background:#4f7f3a}
.primal-shell[data-input="touch"] .pad-l{grid-area:1/3;width:46px!important;height:46px!important;align-self:start;justify-self:end;background:#6f5b8a}
.primal-shell[data-input="touch"][data-phase="playing"] .toast{bottom:calc(var(--touch-h,0px) + 96px)}
.primal-shell[data-input="touch"][data-phase="playing"] .run-info{bottom:auto;right:150px}
@media (max-width:420px){.primal-shell[data-input="touch"][data-phase="playing"] .joystick{width:116px;height:116px;flex-basis:116px}
  .primal-shell[data-input="touch"][data-phase="playing"] .touch-controls>div:last-child{grid-template-columns:repeat(3,52px);grid-template-rows:repeat(3,52px)}
  .primal-shell[data-input="touch"][data-phase="playing"] .touch-controls>div:last-child button{width:56px;height:56px}}
.primal-shell[data-input="touch"][data-phase="playing"] .meat-progress{left:50%;transform:translateX(-50%);width:min(300px,calc(100% - 32px));bottom:calc(var(--touch-h,0px) + 10px)!important}
@media (orientation:landscape){.primal-shell[data-input="touch"][data-phase="playing"] .meat-progress{width:min(300px,calc(100% - 440px));bottom:calc(env(safe-area-inset-bottom,0px) + 14px)!important}
  .primal-shell[data-input="touch"][data-phase="playing"] .toast{bottom:calc(env(safe-area-inset-bottom,0px) + 86px)}}
/* Touch HUD: attack/ability cooldowns show on the round buttons (a dark sweep that empties as they recharge;
   EVNE dims while stamina is too low), so the bottom bars and long labels are not needed. */
.primal-shell[data-input="touch"][data-phase="playing"] .action-cooldowns,.primal-shell[data-input="touch"][data-phase="playing"] #skill-label,.primal-shell[data-input="touch"][data-phase="playing"] #terrain-label{display:none}
.primal-shell[data-input="touch"][data-phase="playing"] .run-info{right:auto;max-width:calc(100% - 140px);padding:3px 8px;gap:2px 10px;font-size:9px}
.primal-shell[data-input="touch"] .pad-a,.primal-shell[data-input="touch"] .pad-b{position:relative}
.primal-shell[data-input="touch"] .pad-a::after,.primal-shell[data-input="touch"] .pad-b::after{content:"";position:absolute;inset:0;border-radius:50%;pointer-events:none;background:conic-gradient(#0b100dcc calc(var(--cd,0)*360deg),transparent 0)}
.primal-shell[data-input="touch"] .pad-b.pad-tired{filter:saturate(.35) brightness(.7)}
/* Landscape phones: smaller top HUD and food bar so the middle of the screen stays free. */
@media (orientation:landscape) and (max-height:520px){
  .primal-shell[data-input="touch"][data-phase="playing"] .hud-card{transform:scale(.78);transform-origin:top left}
  .primal-shell[data-input="touch"][data-phase="playing"] .hunt-counter{transform:scale(.8);transform-origin:top right}
  .primal-shell[data-input="touch"][data-phase="playing"] .meat-progress{padding:4px 8px;font-size:9px}
  .primal-shell[data-input="touch"][data-phase="playing"] .joystick{width:118px;height:118px;flex-basis:118px}
}

/* Hidden admin panel (src/admin.js): developer tool, only after the secret tap code. */
.admin-fab{position:fixed;left:8px;bottom:8px;z-index:9998;padding:4px 8px;font:700 11px/1 monospace;color:#fff;background:#8d2028;border:2px solid #edd0a0;border-radius:6px;opacity:.85;cursor:pointer}
.admin-panel{position:fixed;inset:auto 8px 44px 8px;max-width:520px;max-height:min(78vh,640px);overflow:auto;z-index:9999;padding:10px 12px;color:#edd0a0;background:#14241ce6;border:2px solid #8d2028;border-radius:10px;font:13px/1.35 system-ui,sans-serif;box-shadow:0 8px 24px #0009}
.admin-panel[hidden]{display:none}
.admin-panel header{display:flex;gap:8px;align-items:center;margin-bottom:6px}
.admin-panel header span{flex:1;font-size:11px;opacity:.8}
.admin-panel header button{min-width:32px;min-height:32px;font-size:20px}
.admin-panel h3{margin:8px 0 4px;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#dfbc52}
.admin-panel section{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.admin-panel h3{flex-basis:100%}
.admin-panel button,.admin-panel select{min-height:34px;padding:4px 10px;font:inherit;color:#14241c;background:#edd0a0;border:0;border-radius:6px;cursor:pointer}
.admin-panel label{display:flex;gap:4px;align-items:center}
.admin-panel button[data-admin=off]{background:#c6663c;color:#fff}
.admin-log{min-height:1.4em;margin:8px 0 0;color:#a2d4c1}
.share-ask{border:1px solid #e9b75a;padding:10px 12px;margin:10px 0;text-align:center}.share-ask p{margin:6px 0;font-size:.9em}.share-ask .actions{justify-content:center}
/* hudLayouts (2026-10-16): PC HUD layouts A/B/C. app.js sets data-hud per frame; touch always stays classic. */
.hud-x{display:none}
.hud-picker{margin:14px 0;padding:12px;border:1px solid #c3a35c66;background:#101b16cc;text-align:left}.hud-picker>b{font-size:12px;letter-spacing:2px;color:#dfbd72}.hud-picker>small{font-size:11px;color:#8e9d87}
.hud-picks{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:10px 0 8px}
.hud-picks button{display:flex;flex-direction:column;gap:6px;padding:8px;text-align:left;font-size:12px}.hud-picks button small{font-size:10px;color:#b6c0a9;line-height:1.4}
.hud-picks button.picked{border-color:#dfbc52;box-shadow:inset 0 0 0 2px #dfbc52;background:#2d4433}
.hud-thumb{position:relative;display:block;aspect-ratio:16/9;background:radial-gradient(circle at 30% 70%,#3c6436,#26412a 60%,#1d3322);border:1px solid #50623d;border-radius:3px;overflow:hidden}
.hud-thumb i{position:absolute;display:block;border-radius:1px}.hud-thumb .thumb-player{left:48%;top:47%;width:4%;height:7%;background:#d9a066;border-radius:40%}
.settings .hud-picker{margin:22px 0}
.primal-shell:is([data-hud="a"],[data-hud="b"],[data-hud="c"])[data-phase] :is(.run-info,.meat-progress){display:none!important}
.primal-shell:is([data-hud="a"],[data-hud="b"],[data-hud="c"]) :is(#food-chip,#dna-chip){display:none!important}
.primal-shell:is([data-hud="a"],[data-hud="c"])[data-phase="playing"] footer .control-hints{visibility:hidden}
.primal-shell:is([data-hud="a"],[data-hud="b"],[data-hud="c"]) .hud #meat-label{font-size:calc(18px*var(--hud-scale,1));margin-top:4px}
.primal-shell:is([data-hud="a"],[data-hud="b"],[data-hud="c"]) .toast{bottom:auto;top:110px}
.primal-shell:is([data-hud="a"],[data-hud="c"]) :is(.meter.xp,.meter.goal){display:block}
.primal-shell:is([data-hud="a"],[data-hud="c"]) #xp-label{display:block;font-size:calc(10px*var(--hud-scale,1));letter-spacing:1px;color:#b6c0a9;font-weight:700}
.primal-shell:is([data-hud="a"],[data-hud="b"],[data-hud="c"]) .goal-row{display:flex;justify-content:space-between;gap:12px;margin-top:6px;font-size:calc(12px*var(--hud-scale,1));font-weight:700;color:#efdfb8}
.meter.xp i{background:#c3a35c}.meter.goal{width:100%!important;height:calc(7px*var(--hud-scale,1))}.meter.goal i{background:#e9b75a}
.hud-actions{position:absolute;left:50%;bottom:14px;transform:translateX(-50%);display:flex;gap:14px;align-items:flex-end;padding:10px 16px 8px;background:#101b16e0;border:1px solid #50623d88;border-radius:10px;pointer-events:none;user-select:none;zoom:var(--hud-scale,1)}
.hud-slot{--s:54px;position:relative;min-width:var(--s);display:flex;flex-direction:column;align-items:center}
.hud-slot.small{--s:40px;opacity:.88}
.slot-icon{width:var(--s);height:var(--s);box-sizing:border-box;border:2px solid #657044;border-radius:8px;background:#14241c;display:grid;place-items:center;font-size:20px;font-weight:800;color:#efdfb8;overflow:hidden}
.slot-icon img{width:70%;height:70%;object-fit:contain;image-rendering:pixelated}
.hud-slot .slot-cd{position:absolute;left:50%;top:0;width:var(--s);height:var(--s);transform:translateX(-50%);border-radius:8px;background:conic-gradient(#000b calc(var(--cd,0)*360deg),transparent 0)}
.hud-slot[data-ready="true"] .slot-icon{border-color:#dfbc52;box-shadow:0 0 10px #dfbc5266}
.hud-slot[data-tired="true"] .slot-icon{border-color:#de954a}
.hud-slot kbd{position:relative;margin-top:-9px;background:#23352b;border:1px solid #c3a35c;border-radius:3px;font-size:10px;font-weight:800;padding:0 5px;color:#f1dfbd;white-space:nowrap}
.hud-slot small{margin-top:3px;font-size:10px;color:#b6c0a9;white-space:nowrap;font-weight:600}
.slot-gap{width:1px;align-self:stretch;background:#50623d}
.hud-prompt{position:absolute;left:50%;bottom:122px;transform:translateX(-50%);padding:5px 14px;background:#101b16cc;border:1px solid #657044;border-radius:20px;font-size:calc(12px*var(--hud-scale,1));color:#efdfb8;pointer-events:none;white-space:nowrap}
/* A: tidy corners. */
.primal-shell[data-hud="a"] .hud{align-items:flex-start}
.primal-shell[data-hud="a"] .hud-card{border-radius:10px;padding:10px 14px 10px 10px;gap:12px;background:#101b16e0}
.primal-shell[data-hud="a"] .hud-bars .meter{width:calc(220px*var(--hud-scale,1))}.primal-shell[data-hud="a"] .hud-bars .meter.health{height:calc(14px*var(--hud-scale,1))}
.primal-shell[data-hud="a"] .hud .hunt-counter{min-width:calc(250px*var(--hud-scale,1));background:#101b16e0;border:1px solid #50623d88;padding:10px 12px;border-radius:10px;text-align:left}
/* B: focus on the middle. */
